package android.app;
public final class ApplicationExitInfo {public static final int REASON_CRASH=4,REASON_CRASH_NATIVE=5,REASON_ANR=6;private final int reason,pid;private final long timestamp;public ApplicationExitInfo(int reason,long timestamp,int pid){this.reason=reason;this.timestamp=timestamp;this.pid=pid;}public int getReason(){return reason;}public long getTimestamp(){return timestamp;}public int getPid(){return pid;}public String getDescription(){throw new AssertionError("Raw exit description read");}public java.io.InputStream getTraceInputStream(){throw new AssertionError("Private OS trace read");}}
